Date: Sat, 21 Nov 2026 16:10:41 +0100
Subject: [PATCH] libtaskmanager: Put a window on the screen showing most of it

A window whose centre was on no screen went to the screen with the nearest
corner, so a tall window hanging off the bottom of one screen could show up
in a lower neighbour's task manager. Pick the screen with most overlap.

BUG: 512147
---
 libtaskmanager/tasktools.cpp         | 20 ++++++++++++++++++++
 libtaskmanager/tasktools.h           | 10 ++++++++++
 libtaskmanager/waylandtasksmodel.cpp |  2 +-
 3 files changed, 31 insertions(+), 1 deletion(-)

diff --git a/libtaskmanager/tasktools.cpp b/libtaskmanager/tasktools.cpp
index 98542d332f..c50973e311 100644
--- a/libtaskmanager/tasktools.cpp
+++ b/libtaskmanager/tasktools.cpp
@@ -482,6 +482,26 @@ QRect screenGeometry(const QPoint &pos)
     return screenGeometry;
 }

+QRect screenGeometry(const QRect &windowGeometry)
+{
+    // The screen showing the largest part of the window, so a window hanging off one screen's
+    // edge isn't given to another screen whose corner happens to be closer to its centre
+    QRect bestGeometry;
+    qint64 largestArea = 0;
+
+    for (const QScreen *screen : QGuiApplication::screens()) {
+        const QRect overlap = screen->geometry().intersected(windowGeometry);
+        const qint64 area = qint64(overlap.width()) * overlap.height();
+        if (area > largestArea) {
+            largestArea = area;
+            bestGeometry = screen->geometry();
+        }
+    }
+
+    // Entirely off-screen: fall back to the screen closest to its centre
+    return largestArea > 0 ? bestGeometry : screenGeometry(windowGeometry.center());
+}
+
 void runApp(const KService::Ptr &service, const QList<QUrl> &urls)
 {
     Q_ASSERT(service);
diff --git a/libtaskmanager/tasktools.h b/libtaskmanager/tasktools.h
index 72de459b6c..5f41215213 100644
--- a/libtaskmanager/tasktools.h
+++ b/libtaskmanager/tasktools.h
@@ -140,6 +140,16 @@ TASKMANAGER_EXPORT bool appsMatch(const QModelIndex &a, const QModelIndex &b);
  */
 TASKMANAGER_EXPORT QRect screenGeometry(const QPoint &pos);

+/**
+ * Given a window's geometry in global coordinates, returns the geometry of
+ * the screen showing the largest part of it, or of the screen closest to its
+ * center if it is entirely off-screen.
+ *
+ * @param windowGeometry Window geometry in global space.
+ * @return The geometry of the screen the window is mostly on.
+ */
+TASKMANAGER_EXPORT QRect screenGeometry(const QRect &windowGeometry);
+
 /**
